import React, { useState, useEffect } from "react";
import { Box, Typography, Button } from "@mui/material";
import { useNavigate } from "react-router-dom";

const backgroundImages = [
  "/Background19.jpg",
  "/Background20.jpg",
  "/Background21.jpg",
  "/Background22.jpg",
];

export default function HomePage() {
  const [currentBackground, setCurrentBackground] = useState(0);
  const [showCards, setShowCards] = useState(false); // State to control card section visibility
  const [hideHomeContent, setHideHomeContent] = useState(false); // State to hide home content
  const navigate = useNavigate();

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentBackground((prev) => (prev + 1) % backgroundImages.length);
    }, 3000);

    return () => clearInterval(interval);
  }, []);

  // Function to handle scroll on button click and show card section
  const handleBookNowClick = () => {
    const cardSection = document.getElementById("card-section");
    if (cardSection) {
      cardSection.scrollIntoView({ behavior: "smooth" });
    }
    setShowCards(true); // Show the card section after button click
    setHideHomeContent(true); // Hide home content after button click
  };

  return (
    <Box
      sx={{
        padding: { xs: 2, sm: 4 },
        textAlign: "center",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        minHeight: "100vh",
        backgroundImage: `url(${backgroundImages[currentBackground]})`,
        backgroundSize: "cover",
        backgroundPosition: "center",
        transition: "background-image 0.8s ease-in-out",
        display: hideHomeContent ? "none" : "flex", // Hide home content once "Book Now" is clicked
      }}
    >
      <Typography
        variant="h3"
        gutterBottom
        sx={{
          fontWeight: "bold",
          color: "#b56f76",
          fontSize: { xs: "2rem", sm: "3rem" },
        }}
      >
        EVERPLAN
      </Typography>
      <Typography
        variant="h5"
        gutterBottom
        sx={{
          fontStyle: "italic",
          color: "#6B4F4F",
          fontSize: { xs: "1.2rem", sm: "1.5rem" },
        }}
      >
        Plan, Book, Celebrate—It’s That Easy!
      </Typography>

      <Button
        variant="contained"
        sx={{
          marginTop: 2,
          padding: "10px 20px",
          fontSize: "1rem",
          borderRadius: 2,
          width: "200px",
          backgroundColor: "#F7C5AD",
          color: "#fff",
          "&:hover": {
            backgroundColor: "#F7C5AD",
          },
        }}
        onClick={handleBookNowClick}
      >
        Book Now
      </Button>

      {/* Conditionally render card section below once button is clicked */}
      {showCards && (
        <Box
          id="card-section"
          sx={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fill, minmax(200px, 1fr))",
            gap: 2,
            marginTop: 4,
            padding: 4,
            backgroundColor: "transparent", // Ensure no background color for card section
            boxShadow: "none", // Remove shadow for cards section
          }}
        >
          {["venues", "hair", "makeup", "photographers", "music", "florist", "dresser", "planner"].map((tab) => (
            <Box
              key={tab}
              sx={{
                padding: 2,
                backgroundColor: "#f1f1f1",
                borderRadius: "8px",
                cursor: "pointer",
                boxShadow: "0px 4px 10px rgba(0, 0, 0, 0.1)",
                transition: "transform 0.3s ease",
                "&:hover": {
                  transform: "scale(1.05)",
                },
              }}
              onClick={() => navigate(`/${tab}`)} // Navigate to respective tab
            >
              <Box
                sx={{
                  height: "200px",
                  backgroundColor: "#ddd",
                  borderRadius: "8px",
                  marginBottom: 2,
                }}
              />
              <Typography variant="h6" align="center">
                {tab.charAt(0).toUpperCase() + tab.slice(1)}
              </Typography>
            </Box>
          ))}
        </Box>
      )}
    </Box>
  );
}



